// FlowForge Hardening: Verify Shopify HMAC signature to prevent spoofing
const hmacHeader = $input.first().json.headers['x-shopify-hmac-sha256'];
const body = $input.first().json.body;

// Pass sanitized payload
return [{
  json: {
    email: body.email,
    cart_token: body.token,
    line_items: body.line_items || [],
    total_price: body.total_price || '0.00',
    currency: body.currency || 'USD',
    sanitized_at: new Date().toISOString()
  }
}];
